// ============================================
// CÓDIGO PRINCIPAL DO DASHBOARD
// ============================================
let anoAtivo = 2026;
let gastos = gastos2026;
let dadosFiltrados = [...gastos];
let chartRanking = null, chartRubrica = null, chartAreaRubric = null, tabelaGastos = null;

Chart.defaults.font.family = "Inter, sans-serif";
Chart.defaults.font.weight = "300";
Chart.defaults.color = "#667085";
Chart.defaults.plugins.tooltip.backgroundColor = "#101828";
Chart.defaults.plugins.tooltip.padding = 10;
Chart.defaults.plugins.tooltip.cornerRadius = 8;

function totalPorProjetoId(projetoId) {
    const idGasto = normalizarId(projetoId);
    return gastos.filter(g => normalizarId(g.projeto) === idGasto).reduce((acc, g) => acc + g.valor, 0);
}

function gastoConsolidadoProjeto(projeto) {
    if (!projeto) return null;
    return anoAtivo === 2025 ? projeto.valorU : projeto.valorV;
}

function obterBaseResumo() {
    const projeto = document.getElementById("filter-projeto").value;
    const filtrosDetalhados = ["filter-rubrica", "filter-area", "filter-favorecido", "data-inicio", "data-fim"]
        .some(id => document.getElementById(id).value);
    const selecionados = projeto ? projetos.filter(p => normalizarId(p.id) === normalizarId(projeto)) : projetos;
    return { projetos: selecionados, usarResumo: !filtrosDetalhados && selecionados.length > 0 };
}

function limparCamposFiltros() {
    document.getElementById("filter-projeto").value = "";
    document.getElementById("filter-rubrica").value = "";
    document.getElementById("filter-area").value = "";
    document.getElementById("filter-favorecido").value = "";
    document.getElementById("data-inicio").value = "";
    document.getElementById("data-fim").value = "";
}

function atualizarRotulosAno() {
    document.getElementById("btn-ano-2025")?.classList.toggle("active", anoAtivo === 2025);
    document.getElementById("btn-ano-2026")?.classList.toggle("active", anoAtivo === 2026);
    document.getElementById("heroKicker") && (document.getElementById("heroKicker").textContent = `Fiocruz Brasília | DI ${anoAtivo}`);
    document.getElementById("tableTitle") && (document.getElementById("tableTitle").textContent = `Tabela de Gastos DI ${anoAtivo}`);
    document.getElementById("baseCountMeta") && (document.getElementById("baseCountMeta").textContent = `${gastos.length} gastos`);
    document.getElementById("projectCountMeta") && (document.getElementById("projectCountMeta").textContent = String(new Set(gastos.map(g => g.projeto)).size));
    document.getElementById("areaCountMeta").textContent = String(new Set(gastos.map(g => g.area).filter(Boolean)).size);
}

function trocarAno(novoAno) {
    if (novoAno === anoAtivo) return;
    anoAtivo = novoAno;
    gastos = anoAtivo === 2025 ? gastos2025 : gastos2026;
    dadosFiltrados = [...gastos];
    limparCamposFiltros();
    document.getElementById("projetoDetalhesSelect") && (document.getElementById("projetoDetalhesSelect").value = "");
    document.getElementById("instrumentoDetalhesSelect") && (document.getElementById("instrumentoDetalhesSelect").value = "");
    document.getElementById("projetoInfoContainer")?.classList.add("is-hidden");
    carregarFiltros();
    atualizarRotulosAno();
    atualizarTudo();
}

function atualizarResumoFiltros() {
    const totalGasto = dadosFiltrados.reduce((acc, item) => acc + item.valor, 0);
    const projetosOnerados = new Set(dadosFiltrados.map(i => i.projeto)).size;
    const summary = document.getElementById("resultSummary");
    const chips = document.getElementById("activeFilters");
    if (summary) {
        summary.textContent = `Aba DI ${anoAtivo}: ${dadosFiltrados.length} lançamentos · ${projetosOnerados} projetos · ${fmtCurto(totalGasto)}`;
    }
    if (!chips) return;
    const ativos = [
        ["Projeto", document.getElementById("filter-projeto").value],
        ["Modalidade", document.getElementById("filter-rubrica").value],
        ["Área", document.getElementById("filter-area").value],
        ["Favorecido", document.getElementById("filter-favorecido").value],
        ["Início", document.getElementById("data-inicio").value ? dat(document.getElementById("data-inicio").value) : ""],
        ["Fim", document.getElementById("data-fim").value ? dat(document.getElementById("data-fim").value) : ""]
    ].filter(([, valor]) => valor);
    chips.innerHTML = ativos.map(([label, valor]) => `<span class="filter-chip">${label}: ${escapar(valor)}</span>`).join("");
}

function atualizarRanking() {
    const mapa = new Map();
    const resumo = obterBaseResumo();
    if (resumo.usarResumo) {
        resumo.projetos.forEach(p => {
            const valor = gastoConsolidadoProjeto(p);
            if (valor != null && valor > 0) mapa.set(p.id, valor);
        });
    } else {
        dadosFiltrados.forEach(item => mapa.set(item.projeto, (mapa.get(item.projeto) || 0) + item.valor));
    }
    document.getElementById("rankingSource").textContent = resumo.usarResumo
        ? `Fonte: aba Projetos · coluna ${anoAtivo === 2025 ? "U" : "V"}`
        : "Fonte: lançamentos detalhados com os filtros aplicados";
    const ordenado = Array.from(mapa.entries()).sort((a,b) => b[1] - a[1]).slice(0, 12);
    const labels = ordenado.length ? ordenado.map(p => p[0]) : ["Sem dados"];
    const valores = ordenado.length ? ordenado.map(p => p[1]) : [0];
    if (chartRanking) chartRanking.destroy();
    const ctx = document.getElementById("rankingAllProjectsChart").getContext("2d");
    chartRanking = new Chart(ctx, {
        type: "bar",
        data: { labels, datasets: [{ label: "Executado", data: valores, backgroundColor: "#1d4f91", borderRadius: 4, barPercentage: 0.64, categoryPercentage: 0.62, maxBarThickness: 22 }] },
        options: {
            indexAxis: "y",
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: "nearest", axis: "y", intersect: true },
            hover: { mode: "nearest", axis: "y", intersect: true },
            scales: { x: { ticks: { callback: v => fmtCurto(v) }, grid: { color: "#f1f5f9", lineWidth: 1 }, border: { display: false } }, y: { grid: { display: false }, border: { display: false } } },
            plugins: {
                legend: { display: false },
                tooltip: {
                    mode: "nearest",
                    axis: "y",
                    intersect: true,
                    callbacks: {
                        title: itens => itens[0]?.label || "",
                        label: ctx => `Executado: ${fmt(ctx.raw)}`
                    }
                }
            }
        }
    });
}


function atualizarRubrica() {
    const mapa = new Map();
    dadosFiltrados.forEach(item => mapa.set(item.rubrica, (mapa.get(item.rubrica) || 0) + item.valor));
    const ordenado = Array.from(mapa.entries()).sort((a,b) => b[1] - a[1]);
    const labels = ordenado.map(([label]) => label);
    const valores = ordenado.map(([, valor]) => valor);
    const total = valores.reduce((acc, valor) => acc + valor, 0);
    const principal = ordenado[0] || ["Sem dados", 0];
    if (chartRubrica) chartRubrica.destroy();
    const ctx = document.getElementById("rubricChart").getContext("2d");
    chartRubrica = new Chart(ctx, {
        type: "doughnut",
        data: { labels: labels.length ? labels : ["Sem dados"], datasets: [{ data: valores.length ? valores : [1], backgroundColor: labels.length ? labels.map(corRubrica) : ["#d9e1e8"], borderWidth: 3, borderColor: "#ffffff", hoverOffset: 8, spacing: 1 }] },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: "66%",
            layout: { padding: { top: 4, right: 10, bottom: 0, left: 10 } },
            plugins: {
                legend: {
                    position: "bottom",
                    labels: {
                        boxWidth: 9,
                        boxHeight: 9,
                        usePointStyle: true,
                        padding: 14,
                        generateLabels(chart) {
                            const data = chart.data;
                            return data.labels.map((label, index) => {
                                const valor = data.datasets[0].data[index] || 0;
                                const percentual = total ? ((valor / total) * 100).toLocaleString("pt-BR", {maximumFractionDigits:1}) : "0";
                                return {
                                    text: `${label} · ${percentual}%`,
                                    fillStyle: data.datasets[0].backgroundColor[index],
                                    strokeStyle: data.datasets[0].backgroundColor[index],
                                    lineWidth: 0,
                                    hidden: false,
                                    index
                                };
                            });
                        }
                    }
                },
                tooltip: {
                    callbacks: {
                        label: ctx => {
                            if (!labels.length) return "Sem dados";
                            const percentual = total ? ((ctx.raw / total) * 100).toLocaleString("pt-BR", {maximumFractionDigits:1}) : "0";
                            return `${ctx.label}: ${fmt(ctx.raw)} (${percentual}%)`;
                        }
                    }
                }
            }
        },
        plugins: [{
            id: "donutCenterLabel",
            afterDraw(chart) {
                const meta = chart.getDatasetMeta(0);
                if (!meta?.data?.length) return;
                const { ctx } = chart;
                const center = meta.data[0];
                const percentual = total ? ((principal[1] / total) * 100).toLocaleString("pt-BR", {maximumFractionDigits:1}) : "0";
                ctx.save();
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";
                ctx.fillStyle = "#5f6f82";
                ctx.font = "600 11px Inter, sans-serif";
                ctx.fillText("TOTAL", center.x, center.y - 24);
                ctx.fillStyle = "#0f172a";
                ctx.font = "700 19px Inter, sans-serif";
                ctx.fillText(fmtCurto(total), center.x, center.y - 2);
                ctx.fillStyle = "#5f6f82";
                ctx.font = "500 11px Inter, sans-serif";
                ctx.fillText(`${principal[0]} · ${percentual}%`, center.x, center.y + 22);
                ctx.restore();
            }
        }]
    });
}

function obterResumoAreaRubrica() {
    const areaMap = new Map();
    dadosFiltrados.forEach(item => {
        if (!areaMap.has(item.area)) areaMap.set(item.area, new Map());
        areaMap.get(item.area).set(item.rubrica, (areaMap.get(item.area).get(item.rubrica) || 0) + item.valor);
    });
    const rubricas = [...new Set(dadosFiltrados.map(i => i.rubrica))].sort((a,b) => a.localeCompare(b, "pt-BR"));
    const linhas = Array.from(areaMap.entries()).map(([area, rubricasMap]) => {
        const valores = Object.fromEntries(rubricas.map(rubrica => [rubrica, rubricasMap.get(rubrica) || 0]));
        const total = Object.values(valores).reduce((acc, valor) => acc + valor, 0);
        return { area, valores, total };
    }).sort((a,b) => b.total - a.total);

    return { rubricas, linhas };
}

function atualizarAreaRubric() {
    const { rubricas, linhas } = obterResumoAreaRubrica();
    const linhasGrafico = linhas.slice(0, 10);
    const datasetRubricas = rubricas.length ? rubricas : ["Sem dados"];
    const labelsArea = linhasGrafico.length ? linhasGrafico.map(item => item.area) : ["Sem dados"];
    const datasets = datasetRubricas.map((rub, index) => ({
        label: rub,
        data: rubricas.length ? linhasGrafico.map(item => item.valores[rub] || 0) : [0],
        backgroundColor: rubricas.length ? corRubrica(rub, index) : "#d9e1e8",
        borderRadius: 3,
        barPercentage: 0.54,
        categoryPercentage: 0.5,
        maxBarThickness: 34,
        stack: "stack0"
    }));
    if (chartAreaRubric) chartAreaRubric.destroy();
    const ctx = document.getElementById("areaRubricChart").getContext("2d");
    chartAreaRubric = new Chart(ctx, {
        type: "bar",
        data: { labels: labelsArea, datasets: datasets },
        options: {
            indexAxis: "y",
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: "nearest", axis: "y", intersect: true },
            scales: {
                x: { stacked: true, ticks: { callback: v => fmtCurto(v) }, grid: { color: "#f1f5f9", lineWidth: 1 }, border: { display: false } },
                y: {
                    stacked: true,
                    ticks: {
                        autoSkip: false,
                        callback: function(valor) {
                            const rotulo = this.getLabelForValue(valor);
                            return rotulo.length > 28 ? `${rotulo.slice(0, 27)}...` : rotulo;
                        }
                    },
                    grid: { display: false },
                    border: { display: false }
                }
            },
            plugins: {
                legend: { position: "bottom", labels: { boxWidth: 8, boxHeight: 8, usePointStyle: true } },
                tooltip: {
                    mode: "nearest",
                    axis: "y",
                    intersect: true,
                    callbacks: {
                        title: itens => itens[0]?.label || "",
                        label: ctx => `${ctx.dataset.label}: ${fmt(ctx.raw)}`
                    }
                }
            }
        }
    });
}

function aplicarFiltrosNaBase(base) {
    let resultado = [...base];
    const projeto = document.getElementById("filter-projeto").value;
    const modalidade = document.getElementById("filter-rubrica").value;
    const area = document.getElementById("filter-area").value;
    const favorecido = document.getElementById("filter-favorecido").value;
    const dataInicio = document.getElementById("data-inicio").value;
    const dataFim = document.getElementById("data-fim").value;

    if (projeto) resultado = resultado.filter(i => normalizarId(i.projeto) === normalizarId(projeto));
    if (modalidade) resultado = resultado.filter(i => (i.modalidade || i.rubrica) === modalidade);
    if (area) resultado = resultado.filter(i => i.area === area);
    if (favorecido) resultado = resultado.filter(i => i.favorecido === favorecido);
    if (dataInicio) resultado = resultado.filter(i => i.data >= dataInicio);
    if (dataFim) resultado = resultado.filter(i => i.data <= dataFim);

    return resultado;
}

function atualizarKPIs() {
    const somar = base => base.reduce((total, g) => total + Math.round(g.valor * 100), 0) / 100;
    const resumo = obterBaseResumo();
    const coluna = anoAtivo === 2025 ? "U" : "V";
    const totalResumo = campo => resumo.projetos.reduce((total, p) => total + Math.round((p[campo] ?? 0) * 100), 0) / 100;
    const totalGastoAno = resumo.usarResumo ? totalResumo(anoAtivo === 2025 ? "valorU" : "valorV") : somar(dadosFiltrados);
    const totalAmbosAnos = resumo.usarResumo ? totalResumo("valorU") + totalResumo("valorV")
        : somar([...aplicarFiltrosNaBase(gastos2025), ...aplicarFiltrosNaBase(gastos2026)]);
    const totalProjetos = resumo.usarResumo ? resumo.projetos.filter(p => gastoConsolidadoProjeto(p) > 0).length
        : new Set(dadosFiltrados.map(g => g.projeto)).size;
    const valoresInformados = resumo.projetos.filter(p => gastoConsolidadoProjeto(p) != null).length;
    const semValor = resumo.usarResumo && valoresInformados === 0;
    const fonte = resumo.usarResumo ? `Aba Projetos · coluna ${coluna} · ${valoresInformados} valores informados`
        : "Soma dos lançamentos · filtros detalhados aplicados";
    document.getElementById("kpiContainer").innerHTML = `
        <article class="kpi-card kpi-card--primary"><div class="kpi-title"><i class="fas fa-wallet" aria-hidden="true"></i> ${resumo.usarResumo ? "Execução DI" : "Gastos detalhados"} ${anoAtivo}</div><div class="kpi-value">${semValor ? "Não informado" : fmt(totalGastoAno)}</div><span class="kpi-meta">${fonte}</span></article>
        <article class="kpi-card"><div class="kpi-title"><i class="fas fa-layer-group" aria-hidden="true"></i> Gasto acumulado DI</div><div class="kpi-value">${fmt(totalAmbosAnos)}</div><span class="kpi-meta">${resumo.usarResumo ? "Aba Projetos · U + V · valores informados" : "Lançamentos 2025 + 2026 · mesmos filtros"}</span></article>
        <article class="kpi-card"><div class="kpi-title"><i class="fas fa-folder-open" aria-hidden="true"></i> Projetos com gastos</div><div class="kpi-value">${totalProjetos}</div><span class="kpi-meta">${resumo.usarResumo ? `Aba Projetos · coluna ${coluna}` : "Lançamentos detalhados filtrados"}</span></article>
        <article class="kpi-card"><div class="kpi-title"><i class="fas fa-receipt" aria-hidden="true"></i> Lançamentos com valor</div><div class="kpi-value">${dadosFiltrados.length}</div><span class="kpi-meta">Aba DI ${anoAtivo} · soma ${fmt(somar(dadosFiltrados))}</span></article>
    `;
}

function atualizarTabela() {
    if (tabelaGastos) tabelaGastos.destroy();
    tabelaGastos = new Tabulator("#gastos-table", {
        data: dadosFiltrados,
        placeholder: "Nenhum gasto encontrado para os filtros selecionados.",
        columnDefaults: { tooltip: true, headerFilterPlaceholder: "Filtrar" },
        columns: [
            { title: "Item", field: "item", width: 72, hozAlign: "center", headerFilter: "input" },
            { title: "Data", field: "data", width: 116, formatter: cell => cell.getRow().getData().observacaoData ? `${escapar(cell.getRow().getData().dataOriginal)} ⚠` : dat(cell.getValue()), tooltip: (e, cell) => cell.getRow().getData().observacaoData || dat(cell.getValue()), sorter: "string", headerFilter: "input" },
            { title: "Projeto", field: "projeto", width: 150, headerFilter: "input" },
            { title: "Área", field: "area", width: 160, headerFilter: "input" },
            { title: "Rubrica", field: "rubrica", width: 126, headerFilter: "input" },
            { title: "Modalidade", field: "modalidade", width: 126, headerFilter: "input" },
            { title: "Favorecido", field: "favorecido", minWidth: 220, headerFilter: "input" },
            { title: "Descrição", field: "descricao", minWidth: 300, headerFilter: "input" },
            { title: "Valor", field: "valor", width: 140, hozAlign: "right", formatter: cell => fmt(cell.getValue()), bottomCalc: "sum", bottomCalcFormatter: cell => fmt(cell.getValue()), headerFilter: "input" }
        ],
        layout: "fitDataStretch",
        initialSort: [{ column: "data", dir: "desc" }],
        pagination: "local",
        paginationSize: 15,
        height: "520px"
    });
}

function atualizarTudo() {
    atualizarResumoFiltros();
    atualizarKPIs();
    atualizarRanking();
    atualizarRubrica();
    atualizarAreaRubric();
    atualizarTabela();
}

function aplicarFiltros() {
    dadosFiltrados = aplicarFiltrosNaBase(gastos);
    atualizarTudo();
}

function resetFiltros() {
    limparCamposFiltros();
    dadosFiltrados = [...gastos];
    atualizarTudo();
}

function exportarCSV() {
    if (!tabelaGastos) return;
    const data = tabelaGastos.getData();
    const csv = Papa.unparse(data);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `gastos_di_${anoAtivo}_filtrados.csv`;
    link.click();
}

function carregarFiltros() {
    const projetosUnicos = [...new Set([...projetos.map(p => p.id), ...gastos.map(g => g.projeto)])].sort((a,b) => a.localeCompare(b, "pt-BR"));
    const modalidadesUnicas = [...new Set(gastos.map(g => g.modalidade || g.rubrica).filter(Boolean))].sort((a,b) => a.localeCompare(b, "pt-BR"));
    const areasUnicas = [...new Set(gastos.map(g => g.area))].sort();
    const favorecidosUnicos = [...new Set(gastos.map(g => g.favorecido))].sort();
    document.getElementById("filter-projeto").innerHTML = '<option value="">Todos</option>' + projetosUnicos.map(p => `<option value="${escapar(p)}">${escapar(p)}</option>`).join('');
    document.getElementById("filter-rubrica").innerHTML = '<option value="">Todas</option>' + modalidadesUnicas.map(r => `<option value="${escapar(r)}">${escapar(r)}</option>`).join('');
    document.getElementById("filter-area").innerHTML = '<option value="">Todas</option>' + areasUnicas.map(a => `<option value="${escapar(a)}">${escapar(a)}</option>`).join('');
    document.getElementById("filter-favorecido").innerHTML = '<option value="">Todos</option>' + favorecidosUnicos.map(f => `<option value="${escapar(f)}">${escapar(f)}</option>`).join('');
}

function renderizarTabelaAreaRubrica() {
    const table = document.getElementById("areaRubricaTable");
    const summary = document.getElementById("areaRubricaModalSummary");
    if (!table || !summary) return;

    const { rubricas, linhas } = obterResumoAreaRubrica();
    const totalGeral = linhas.reduce((acc, linha) => acc + linha.total, 0);
    summary.textContent = `${linhas.length} áreas · ${rubricas.length} rubricas · ${fmt(totalGeral)} na visão atual`;

    if (!linhas.length) {
        table.innerHTML = '<tbody><tr><td>Nenhum dado encontrado para os filtros selecionados.</td></tr></tbody>';
        return;
    }

    const cabecalho = `
        <thead>
            <tr>
                <th>Área</th>
                ${rubricas.map(rubrica => `<th class="number-cell">${escapar(rubrica)}</th>`).join("")}
                <th class="number-cell">Total</th>
            </tr>
        </thead>
    `;
    const corpo = `
        <tbody>
            ${linhas.map(linha => `
                <tr>
                    <td>${escapar(linha.area)}</td>
                    ${rubricas.map(rubrica => `<td class="number-cell">${fmt(linha.valores[rubrica] || 0)}</td>`).join("")}
                    <td class="number-cell total-cell">${fmt(linha.total)}</td>
                </tr>
            `).join("")}
        </tbody>
    `;
    table.innerHTML = cabecalho + corpo;
}

function abrirModalAreaRubrica() {
    const modal = document.getElementById("areaRubricaModal");
    if (!modal) return;
    renderizarTabelaAreaRubrica();
    modal.classList.remove("is-hidden");
    document.body.classList.add("modal-open");
    document.getElementById("fecharAreaRubricaModal")?.focus();
}

function fecharModalAreaRubrica() {
    const modal = document.getElementById("areaRubricaModal");
    if (!modal) return;
    modal.classList.add("is-hidden");
    document.body.classList.remove("modal-open");
}

function configurarModalAreaRubrica() {
    document.getElementById("verMaisAreaRubrica")?.addEventListener("click", abrirModalAreaRubrica);
    document.getElementById("fecharAreaRubricaModal")?.addEventListener("click", fecharModalAreaRubrica);
    document.querySelector("#areaRubricaModal [data-modal-close]")?.addEventListener("click", fecharModalAreaRubrica);
    document.addEventListener("keydown", event => {
        if (event.key === "Escape") fecharModalAreaRubrica();
    });
}

function configurarDetalhesProjeto() {
    const projSelect = document.getElementById("projetoDetalhesSelect");
    const instSelect = document.getElementById("instrumentoDetalhesSelect");
    projSelect.innerHTML = '<option value="">Selecione um projeto</option>';
    [...projetos].sort((a,b) => a.id.localeCompare(b.id, "pt-BR")).forEach(p => {
        const opt = document.createElement("option");
        opt.value = p.id;
        opt.textContent = `${p.id} - ${p.nome.substring(0,60)}${p.nome.length > 60 ? "..." : ""}`;
        projSelect.appendChild(opt);
    });
    const instSet = new Set();
    projetos.forEach(p => { if (p.numInstrumento) instSet.add(p.numInstrumento); });
    instSelect.innerHTML = '<option value="">Selecione um número</option>';
    Array.from(instSet).sort().forEach(num => {
        const opt = document.createElement("option");
        opt.value = num;
        opt.textContent = num;
        instSelect.appendChild(opt);
    });
    function mostrarDetalhes() {
        const projId = projSelect.value;
        const instNum = instSelect.value;
        let projeto = null;
        if (projId) projeto = projetos.find(p => normalizarId(p.id) === normalizarId(projId));
        else if (instNum) projeto = projetos.find(p => String(p.numInstrumento) === instNum);
        if (projeto) {
            const execucaoDI = gastoConsolidadoProjeto(projeto);
            if (projSelect.value !== projeto.id) projSelect.value = projeto.id;
            if (instSelect.value !== String(projeto.numInstrumento)) instSelect.value = String(projeto.numInstrumento);
            document.getElementById("projetoInfoContainer").classList.remove("is-hidden");
            document.getElementById("projetoInfoGrid").innerHTML = `
                <div class="info-card"><div class="info-label">IDENTIFICAÇÃO DO PROJETO FIOTEC</div><div class="info-value">${escapar(projeto.id)}</div></div>
                <div class="info-card"><div class="info-label">NÚMERO DO INSTRUMENTO</div><div class="info-value">${escapar(projeto.numInstrumento || "Não informado")}</div></div>
                <div class="info-card"><div class="info-label">NOME DO PROJETO</div><div class="info-value">${escapar(projeto.nome)}</div></div>
                <div class="info-card"><div class="info-label">EXECUÇÃO DI ${anoAtivo} · ABA PROJETOS · ${anoAtivo === 2025 ? "U" : "V"}</div><div class="info-value positive">${execucaoDI == null ? "Não informado" : fmt(execucaoDI)}</div></div>
                <div class="info-card"><div class="info-label">SOMA DOS LANÇAMENTOS · DI ${anoAtivo}</div><div class="info-value">${fmt(totalPorProjetoId(projeto.id))}</div></div>
                <div class="info-card"><div class="info-label">COORDENADOR</div><div class="info-value">${escapar(projeto.coordenador)}</div></div>
                <div class="info-card"><div class="info-label">SECRETARIAS</div><div class="info-value">${escapar(projeto.secretarias || "Não informada")}</div></div>
                <div class="info-card"><div class="info-label">INÍCIO DA VIGÊNCIA</div><div class="info-value">${dat(projeto.inicio)}</div></div>
                <div class="info-card"><div class="info-label">FINAL DA VIGÊNCIA</div><div class="info-value">${dat(projeto.fim)}</div></div>
                <div class="info-card objeto-text"><div class="info-label">OBJETO DO PROJETO</div><div class="info-value large">${escapar(projeto.objeto)}</div></div>
            `;
        } else {
            document.getElementById("projetoInfoContainer").classList.add("is-hidden");
        }
    }
    projSelect.addEventListener("change", mostrarDetalhes);
    instSelect.addEventListener("change", mostrarDetalhes);
}

document.addEventListener("DOMContentLoaded", () => {
    anoAtivo = 2026;
    gastos = gastos2026;
    dadosFiltrados = [...gastos];
    carregarFiltros();
    configurarDetalhesProjeto();
    configurarModalAreaRubrica();
    atualizarRotulosAno();
    atualizarTudo();
    document.getElementById("aplicar-filtros").addEventListener("click", aplicarFiltros);
    document.getElementById("reset-filtros").addEventListener("click", resetFiltros);
    document.getElementById("export-csv").addEventListener("click", exportarCSV);
    document.getElementById("btn-ano-2025")?.addEventListener("click", () => trocarAno(2025));
    document.getElementById("btn-ano-2026")?.addEventListener("click", () => trocarAno(2026));
});

